-- PT111-S1-Q11. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT111-S1-Q11$batch06$ AND q.stimulus=$batch06$Linguist: Some people have understood certain studies as showing that bilingual children have a reduced “conceptual map” because bilingualism overstresses the child’s linguistic capacities. Vocabulary tests taken by bilingual children appear to show that these children tend to have a smaller vocabulary than do most children of the same age group. But these studies are deeply flawed, since the tests were given in only one language. Dual-language tests revealed that the children often expressed a given concept with a word from only one of their two languages.$batch06$ AND q.prompt=$batch06$The linguist's argument proceeds by$batch06$ AND q.correct_choice=$batch06$E$batch06$) THEN RAISE EXCEPTION 'Question changed: PT111-S1-Q11'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT111-S1-Q11$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT111-S1-Q11'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT111-S1-Q11$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Conclusion$batch06$, $batch06$The studies suggesting bilingual children have a reduced "conceptual map" are deeply flawed.$batch06$), (1, $batch06$Evidence$batch06$, $batch06$The vocabulary tests were given in only one language. Dual-language tests showed the children often knew a concept through a word in just one of their two languages.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The linguist does not argue that bilingualism is good, or that the children's vocabulary is fine. The attack is on how the evidence was gathered. Test a bilingual child in one language and you miss every concept they hold in the other. That is a flaw in the method of collecting the data.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Pointing out a flaw in how the evidence against bilingualism was gathered.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT111-S1-Q11$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$The linguist never argues bilingualism is better than knowing one language, only that this evidence against it is flawed.$batch06$), ($batch06$B$batch06$, $batch06$No inconsistency is shown in the opposing view. The problem is in the testing, not in the view's logic.$batch06$), ($batch06$C$batch06$, $batch06$"Any vocabulary test" goes too far. The linguist's own evidence comes from vocabulary tests, given in both languages. Only the one-language tests are the problem.$batch06$), ($batch06$D$batch06$, $batch06$The studies claimed a *disadvantage* of bilingualism, not an advantage, and the linguist offers no rival explanation for one.$batch06$), ($batch06$E$batch06$, $batch06$The methodological error is testing in only one language. The purported evidence is the smaller vocabulary scores. The problem with bilingualism is the supposed shrunken conceptual map.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT111-S1-Q11$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
